def parse_duration(s):
    total = 0
    i = 0
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            num = int(s[i:j])
            if j < len(s):
                unit = s[j]
                if unit == 'h':
                    total += num * 3600
                    i = j + 1
                elif unit == 'm':
                    total += num * 60
                    i = j + 1
                elif unit == 's':
                    total += num
                    i = j + 1
                else:
                    total += num
                    i = j
            else:
                total += num
                i = j
        else:
            i += 1
    return total

