def flatten(xs):
    result = []
    for item in xs:
        if isinstance(item, (list, tuple)) and len(item) > 1:
            # Flatten only if the nested list has more than 1 element
            for subitem in item:
                if isinstance(subitem, (list, tuple)) and len(subitem) > 1:
                    for subsubitem in subitem:
                        result.append(subsubitem)
                else:
                    result.append(subitem)
        else:
            result.append(item)
    return result

def celsius_to_f(c):
    # Handle numeric strings
    if isinstance(c, str):
        c = float(c)

