def parse_duration(s):
    import re
    s = re.sub(r'\s+', '', s)
    result = 0
    for match in re.finditer(r'(\d+)([smh])?', s):
        num = int(match.group(1))
        unit = match.group(2)
        if unit == 's':
            result += num
        elif unit == 'm':
            result += num * 60
        elif unit == 'h':
            result += num * 3600
    return result

